text-style.fieldName:
with_variable('isim_raw', trim("FIRname"), with_variable('isim', regexp_replace(@isim_raw,'^(FIR|UIR)\s+',''), with_variable('suffix', CASE WHEN "UPPER" = 'U' AND "LOWER" = 'L' THEN ' FIR/UIR' WHEN "UPPER" = 'U' THEN ' UIR' WHEN "LOWER" = 'L' THEN ' FIR' ELSE '' END,
"ICAOCODE" || ' ' || @isim || @suffix
)))

